effect.shader:
vec4 u_xlat0;
bvec2 u_xlatb0;
vec4 u_xlat1;
float u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
vec2 u_xlat12;
bvec2 u_xlatb12;
void main()
{
    u_xlat0.xy = acScreenNorm.yx + vec2(-0.5, -0.5);
    u_xlat0.xy = u_xlat0.xy * vec2(vec2(_zoom, _zoom));
    u_xlat12.x = _strength * 0.5;
    u_xlat0.xy = u_xlat0.xy + u_xlat0.xy;
    u_xlat1.xy = -abs(u_xlat0.xy) * abs(u_xlat0.xy) + vec2(1.0, 1.0);
    u_xlat12.y = u_xlat1.x * (-u_xlat12.x) + 1.0;
    u_xlat12.x = u_xlat1.y * u_xlat12.x + 1.0;
    u_xlat12.xy = max(u_xlat12.xy, vec2(0.0, 0.0));
    u_xlat12.xy = min(u_xlat12.xy, vec2(2.0, 2.0));
    u_xlat1.xy = u_xlat0.yx / u_xlat12.yx;
    u_xlat0.xy = u_xlat1.xy * vec2(0.5, 0.5) + vec2(0.5, 0.5);
    u_xlatb12.xy = equal(ivec4(ivec4(int(_border), int(_border), int(_border), int(_border))), ivec4(2, 0, 2, 0)).xy;
    if(u_xlatb12.x){
        u_xlat1 = texture(SourceTexMirror, u_xlat0.xy);
    } else {
        u_xlat1 = texture(inputImg, u_xlat0.xy);
    }
    u_xlatb2.xy = lessThan(u_xlat0.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb0.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlatb0.x = u_xlatb0.x || u_xlatb2.x;
    u_xlatb0.x = u_xlatb2.y || u_xlatb0.x;
    u_xlatb0.x = u_xlatb0.y || u_xlatb0.x;
    u_xlatb0.x = u_xlatb0.x && u_xlatb12.y;
    u_xlat0 = (u_xlatb0.x) ? vec4(0.0, 0.0, 0.0, 0.0) : u_xlat1;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2 = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2 : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
